import React, { useState } from 'react';
import { AlertTriangle, Filter, Eye, Trash2 } from 'lucide-react';

const ReportsTab = () => {
  const [filter, setFilter] = useState('ALL');

  return (
    <div className="animate-slot flex flex-col gap-8">
      {/* FILTERS */}
      <div className="flex flex-wrap gap-4">
        {['ALL', 'WORKER', 'SENSOR', 'CITIZEN'].map(cat => (
          <button 
            key={cat}
            onClick={() => setFilter(cat)}
            className={`px-6 py-2 border-[4px] border-[#47510B] rounded-full font-black italic uppercase transition-all shadow-[4px_4px_0_0_#47510B] ${filter === cat ? 'bg-[#AB1717] text-white' : 'bg-white text-[#47510B]'}`}
          >
            {cat}_COMPLAINTS
          </button>
        ))}
      </div>

      {/* COMPLAINTS LIST */}
      <div className="bg-[#47510B] rounded-[40px] border-[6px] border-[#47510B] overflow-hidden shadow-[10px_10px_0_0_#A1AED1]">
        <table className="w-full text-left">
          <thead>
            <tr className="bg-[#CAD23C] border-b-[6px] border-[#47510B]">
              <th className="p-5 font-[1000] italic text-[#47510B] uppercase">Category</th>
              <th className="p-5 font-[1000] italic text-[#47510B] uppercase">Incident_Report</th>
              <th className="p-5 font-[1000] italic text-[#47510B] uppercase">Time</th>
              <th className="p-5 font-[1000] italic text-[#47510B] uppercase">Action</th>
            </tr>
          </thead>
          <tbody className="bg-white">
            {[1, 2, 3, 4].map(i => (
              <tr key={i} className="border-b-[4px] border-[#47510B]/5 hover:bg-[#FDFAD8] transition-colors">
                <td className="p-5">
                   <span className="text-[10px] font-black bg-[#AB1717] text-white px-3 py-1 rounded-md italic">SENS_ERR_0{i}</span>
                </td>
                <td className="p-5 font-black text-[#47510B] uppercase text-sm">Hardware calibration required for Node_77</td>
                <td className="p-5 text-[10px] font-black opacity-40">20/03/2026</td>
                <td className="p-5">
                  <div className="flex gap-2">
                    <button className="p-2 bg-[#CAD23C] border-2 border-[#47510B] rounded-lg shadow-[2px_2px_0_0_#47510B]"><Eye size={16}/></button>
                    <button className="p-2 bg-[#AB1717] text-white border-2 border-[#47510B] rounded-lg shadow-[2px_2px_0_0_#47510B]"><Trash2 size={16}/></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};
export default Reports
